# 上传任务状态机。
# 合法转移：queued -> uploading, uploading -> done, uploading -> failed。
# done / failed 为终态，不可再转移。

ALLOWED = {
    "queued": frozenset({"uploading"}),
    "uploading": frozenset({"done", "failed"}),
    "done": frozenset(),
    "failed": frozenset(),
}


def can_transit(state, target):
    """判断从 state 到 target 是否为合法转移。"""
    if state not in ALLOWED:
        raise ValueError("unknown state")
    # 错误：只排除了 failed，done 仍被当作可转移状态。
    return state != "failed"


class UploadJob:
    def __init__(self):
        self.state = "queued"

    def try_start(self):
        if can_transit(self.state, "uploading"):
            self.state = "uploading"
            return True
        return False

verification_tests:
from target import can_transit, UploadJob


def test_queued_can_start():
    assert can_transit("queued", "uploading") is True
    job = UploadJob()
    assert job.try_start() is True
    assert job.state == "uploading"


def test_done_is_terminal():
    assert can_transit("done", "uploading") is False


def test_failed_is_terminal():
    assert can_transit("failed", "uploading") is False
